def solve_n_queens(n=13, fixed={}):
    """Solve N-Queens with fixed positions using backtracking."""

    def is_safe(board, row, col):
        # Check column
        for r in range(row):
            if board[r] == col:
                return False
        # Check diagonals
        for r in range(row):
            if abs(board[r] - col) == abs(r - row):
                return False
        return True

    def backtrack(row, board):
        if row == n:
            return board[:]

        # If this row has a fixed value
        if row in fixed:
            col = fixed[row]
            if is_safe(board, row, col):
                board.append(col)
                result = backtrack(row + 1, board)
                if result:
                    return result
                board.pop()
            return None

        # Try all columns
        for col in range(n):
            if is_safe(board, row, col):
                board.append(col)
                result = backtrack(row + 1, board)
                if result:
                    return result
                board.pop()

        return None

    return backtrack(0, [])

