        for i in range(n):
            for j in range(i+1, n):
                if board[i] == board[j]:
                    return False, f"Same column: rows {i} and {j}"
                if abs(board[i] - board[j]) == abs(i - j):
                    return False, f"Same diagonal: rows {i} and {j}"
        return True, "Valid"

